# Shiny app for exploring clustering of a data matrix without writing R code.
# Files in R/ are sourced automatically by shiny::runApp().

library(shiny)
library(ggplot2)
library(umap)
library(Rtsne)
library(dbscan)

ROLE_LABELS <- c(cluster = "agrupamiento", display = "representación", ignore = "ignorar")
MAX_COLOUR_LEVELS <- 20  # text variables with more levels are not used for colour
MAX_SHAPE_LEVELS <- 6    # ggplot2's default shape palette
CLUSTER_CHOICE <- ".cluster"  # value of "Cluster" in the colour and shape selectors
EXAMPLE_FILE <- file.path("examples", "1000g_chr22.csv")  # see examples/README.md

# Two levels of messages. Something that stops an action is a modal dialog
# the user has to close; a warning is a notification (top centre, see CSS).
stop_dialog <- function(title, ...) {
  showModal(modalDialog(title = title, ..., easyClose = TRUE,
                        footer = modalButton("Entendido")))
}

# Evaluate expr; errors as a dialog, warnings as notifications. NULL on error.
with_notifications <- function(expr, title = "No se ha podido ejecutar") {
  withCallingHandlers(
    tryCatch(expr, error = function(e) {
      stop_dialog(title, conditionMessage(e))
      NULL
    }),
    warning = function(w) {
      showNotification(conditionMessage(w), type = "warning", duration = 10)
      invokeRestart("muffleWarning")
    }
  )
}

ui <- fluidPage(
  tags$head(tags$style(HTML("
    #shiny-notification-panel {
      top: 16px; bottom: auto; left: 0; right: 0; margin: 0 auto;
      width: 520px; max-width: calc(100vw - 32px);
    }
    .shiny-notification {
      font-size: 16px; padding: 14px 18px; opacity: 1;
      border-left: 6px solid #0072B2; box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
    }
    .shiny-notification-warning { border-left-color: #E69F00; }
    .shiny-notification-error { border-left-color: #D55E00; }
    .modal-title { font-weight: bold; color: #B03A00; }
    .modal-body { font-size: 16px; }
  "))),
  titlePanel("Agrupamiento sin programar"),
  sidebarLayout(
    sidebarPanel(
      fileInput("file", "Matriz de datos (CSV)", accept = c(".csv", "text/csv")),
      actionButton("load_example", "Cargar ejemplo (1000 Genomas, chr22)"),
      helpText("780 muestras de 26 poblaciones y 500 SNPs (dosis 0, 1, 2) del Proyecto",
               "1000 Genomas, fase 3."),
      fluidRow(
        column(6, selectInput("sep", "Separador",
                              c("Coma" = ",", "Punto y coma" = ";", "Tabulador" = "\t"))),
        column(6, selectInput("dec", "Decimal", c("Punto" = ".", "Coma" = ",")))
      ),
      strong("Papel de las columnas"),
      textOutput("roles_summary"),
      helpText("Se cambia en la pestaña «Variables»."),
      hr(),
      selectInput("dimred", "Reducción de dimensionalidad",
                  c("PCA", "t-SNE", "UMAP"), selected = "PCA"),
      conditionalPanel(
        "input.dimred == 't-SNE'",
        numericInput("perplexity", "Perplejidad (máximo (n - 1) / 3)", 30, min = 1)
      ),
      selectInput("cluster", "Método de agrupamiento",
                  c("k-means", "DBSCAN", "HDBSCAN", "Ninguno" = "none"),
                  selected = "k-means"),
      parameters_panel,
      numericInput("seed", "Semilla", 123, step = 1),
      actionButton("run", "Ejecutar", class = "btn-primary"),
      hr(),
      selectInput("colour_by", "Color",
                  choices = c("(ninguna)" = "", "Cluster" = CLUSTER_CHOICE),
                  selected = CLUSTER_CHOICE),
      selectInput("shape_by", "Forma",
                  choices = c("(ninguna)" = "", "Cluster" = CLUSTER_CHOICE))
    ),
    mainPanel(
      tabsetPanel(
        id = "main",
        tabPanel(
          "Variables",
          helpText("Selecciona filas con un clic (Mayús o Ctrl para varias), o escribe en",
                   "«Buscar» y pulsa «Seleccionar las filtradas». Después elige el papel."),
          div(
            style = "margin-bottom: 10px;",
            actionButton("select_filtered", "Seleccionar las filtradas"),
            actionButton("clear_selection", "Quitar selección"),
            span(style = "margin-left: 1em;", "Pasar a:"),
            actionButton("to_cluster", "Agrupamiento"),
            actionButton("to_display", "Representación"),
            actionButton("to_ignore", "Ignorar")
          ),
          DT::DTOutput("roles_table")
        ),
        tabPanel(
          "Gráfico",
          plotOutput("embedding", height = "550px"),
          textOutput("run_summary"),
          uiOutput("report_button"),
          h4("Variables más asociadas a los clusters"),
          helpText("η² de cada variable de agrupamiento con los clusters de la ejecución",
                   "(sin el ruido): 0 si la variable no distingue los clusters, 1 si los",
                   "separa por completo. «Diferencia» es la media del cluster más alejado",
                   "menos la media global, en desviaciones típicas."),
          DT::DTOutput("association")
        )
      )
    )
  )
)

server <- function(input, output, session) {
  observeEvent(input$cluster, {
    updateTabsetPanel(inputId = "params", selected = input$cluster)
  })

  # P1: data from the user's computer, or the bundled example (P7) ----------
  data_source <- reactiveVal(NULL)
  observeEvent(input$file, {
    data_source(list(path = input$file$datapath, name = input$file$name, example = FALSE))
  })
  observeEvent(input$load_example, {
    updateSelectInput(session, "sep", selected = ",")
    updateSelectInput(session, "dec", selected = ".")
    data_source(list(path = EXAMPLE_FILE, name = basename(EXAMPLE_FILE), example = TRUE))
  })

  raw_data <- reactive({
    src <- data_source()
    req(src)
    sep <- if (src$example) "," else input$sep
    dec <- if (src$example) "." else input$dec
    df <- tryCatch(
      utils::read.csv(src$path, sep = sep, dec = dec, stringsAsFactors = FALSE,
                      check.names = FALSE),
      error = function(e) {
        stop_dialog("No se ha podido leer el CSV", conditionMessage(e),
                    p("Revisa el separador y el decimal."))
        NULL
      }
    )
    req(df)
    validate(need(nrow(df) >= 2, "El archivo tiene menos de 2 filas."))
    df
  })

  # P4: role of each column -------------------------------------------------
  # One role per column, edited in the "Variables" tab. New data resets the
  # roles to their defaults (numeric -> clustering, text -> display).
  roles <- reactiveVal(NULL)
  observeEvent(raw_data(), roles(default_roles(raw_data())))

  # Roles that belong to the current data (NULL while they are being reset).
  current_roles <- reactive({
    r <- roles()
    req(r, identical(names(r), names(raw_data())))
    r
  })

  roles_table_data <- function(df, r) {
    data.frame(
      Columna = names(df),
      Tipo = vapply(df, function(v) class(v)[1], character(1)),
      Faltantes = vapply(df, function(v) sum(is.na(v)), integer(1)),
      Papel = unname(ROLE_LABELS[r]),
      check.names = FALSE
    )
  }

  # The table is drawn once per data set; role changes go through the proxy so
  # the search box and the page are kept.
  output$roles_table <- DT::renderDT({
    df <- raw_data()
    DT::datatable(
      roles_table_data(df, default_roles(df)),
      rownames = FALSE, selection = "multiple",
      options = list(pageLength = 25, lengthMenu = c(10, 25, 100, 1000),
                     language = list(search = "Buscar:"))
    )
  })
  roles_proxy <- DT::dataTableProxy("roles_table")
  observeEvent(current_roles(), {
    DT::replaceData(roles_proxy, roles_table_data(raw_data(), current_roles()),
                    rownames = FALSE, resetPaging = FALSE, clearSelection = "none")
  })

  observeEvent(input$select_filtered, {
    DT::selectRows(roles_proxy, input$roles_table_rows_all)
  })
  observeEvent(input$clear_selection, DT::selectRows(roles_proxy, NULL))

  apply_role <- function(role) {
    rows <- input$roles_table_rows_selected
    if (length(rows) == 0) {
      showNotification("Selecciona antes alguna fila de la tabla.", type = "warning")
      return()
    }
    df <- raw_data()
    r <- assign_role(current_roles(), names(df)[rows], role, df)
    rejected <- attr(r, "rejected")
    if (length(rejected) > 0) {
      more <- if (length(rejected) > 5) sprintf(" y %d más", length(rejected) - 5) else ""
      stop_dialog(
        "Una columna de texto no puede ser de agrupamiento",
        p(sprintf("Se han dejado como estaban: %s%s.",
                  paste(utils::head(rejected, 5), collapse = ", "), more)),
        p("Los métodos de agrupamiento solo trabajan con columnas numéricas. Las columnas",
          "de texto sirven como representación (color o forma) o se ignoran."),
        if (length(rejected) < length(rows)) p("Las columnas numéricas seleccionadas sí han cambiado.")
      )
    }
    attr(r, "rejected") <- NULL
    roles(r)
    DT::selectRows(roles_proxy, NULL)
  }
  observeEvent(input$to_cluster, apply_role("cluster"))
  observeEvent(input$to_display, apply_role("display"))
  observeEvent(input$to_ignore, apply_role("ignore"))

  output$roles_summary <- renderText({
    n <- count_roles(current_roles())
    sprintf("%d de agrupamiento · %d de representación · %d ignoradas",
            n[["cluster"]], n[["display"]], n[["ignore"]])
  })

  # Colour and shape come from the clusters of the run or from display
  # variables, never from clustering variables.
  observe({
    r <- roles()
    choices <- c("(ninguna)" = "",
                 if (!identical(input$cluster, "none")) c("Cluster" = CLUSTER_CHOICE),
                 names(r)[r == "display"])
    keep <- function(x) if (isTRUE(x %in% choices)) x else ""
    updateSelectInput(session, "colour_by", choices = choices,
                      selected = keep(isolate(input$colour_by)))
    updateSelectInput(session, "shape_by", choices = choices,
                      selected = keep(isolate(input$shape_by)))
  })

  # P2 and P3: dimensionality reduction and clustering ------------------------
  # Parameters of the last run; P5 will build the report from here.
  last_run <- reactiveValues(
    time = NULL, file = NULL, method = NULL, params = NULL, seed = NULL,
    roles = NULL, cluster_vars = NULL, n_rows = NULL, n_rows_dropped = NULL,
    cluster_params = NULL, cluster_sizes = NULL, n_noise = NULL
  )

  # Embedding and clusters come from the same click, matrix and rows.

  embedding <- eventReactive(input$run, {
    df <- raw_data()
    if (!isTRUE(is.finite(input$seed))) {
      stop_dialog("Falta la semilla", "La semilla tiene que ser un número.")
      req(FALSE)
    }
    X <- with_notifications(prepare_matrix(df, current_roles()),
                            title = "Revisa el papel de las columnas")
    req(X)
    coords <- with_notifications(
      reduce_dim(X, input$dimred, seed = input$seed, perplexity = input$perplexity),
      title = "No se ha podido calcular la reducción"
    )
    req(coords)

    clusters <- NULL
    if (isTRUE(input$cluster %in% CLUSTER_METHODS)) {
      minpts <- if (input$cluster == "DBSCAN") input$minpts_dbscan else input$minpts_hdbscan
      clusters <- with_notifications(
        get_clusters(X, input$cluster, seed = input$seed, centers = input$centers,
                     nstart = input$nstart, eps = input$eps, minpts = minpts),
        title = "No se ha podido calcular el agrupamiento"
      )
      req(clusters)
    }

    params <- attr(coords, "params")
    if (!is.null(params$perplexity) && params$perplexity < input$perplexity) {
      showNotification(sprintf("Perplejidad reducida a %.2f.", params$perplexity),
                       type = "warning")
    }

    last_run$time <- Sys.time()
    last_run$file <- data_source()$name
    last_run$method <- input$dimred
    last_run$params <- params
    last_run$seed <- input$seed
    last_run$roles <- current_roles()
    last_run$cluster_vars <- colnames(X)
    last_run$n_rows <- nrow(X)
    last_run$n_rows_dropped <- nrow(df) - nrow(X)
    if (is.null(clusters)) {
      last_run$cluster_params <- NULL
      last_run$cluster_sizes <- NULL
      last_run$n_noise <- NULL
    } else {
      sz <- cluster_sizes(clusters)
      last_run$cluster_params <- attr(clusters, "params")
      last_run$cluster_sizes <- stats::setNames(as.integer(sz$sizes), names(sz$sizes))
      last_run$n_noise <- as.integer(sz$noise)
    }

    updateTabsetPanel(session, "main", selected = "Gráfico")
    rows <- attr(X, "rows")
    list(coords = coords, rows = rows, clusters = clusters, data = df[rows, , drop = FALSE],
         X = X)
  })

  # Values for the colour or shape channel: the run's clusters or a display
  # variable; NULL if the choice does not apply to the plotted run.
  aes_values <- function(choice, emb, df) {
    if (identical(choice, CLUSTER_CHOICE)) return(emb$clusters)
    if (nzchar(choice) && choice %in% names(df)) return(df[[choice]])
    NULL
  }
  aes_label <- function(choice) {
    if (identical(choice, CLUSTER_CHOICE)) "Cluster" else if (nzchar(choice)) choice else NULL
  }

  output$embedding <- renderPlot({
    emb <- embedding()
    df <- emb$data  # rows of the run, not of whatever data is loaded now
    plot_df <- data.frame(x = emb$coords[, 1], y = emb$coords[, 2])
    p <- ggplot(plot_df, aes(x = .data$x, y = .data$y))

    colour_by <- input$colour_by
    colour_label <- NULL
    shape_label <- NULL
    v <- aes_values(colour_by, emb, df)
    if (!is.null(v)) {
      if (!is.numeric(v) && length(unique(v)) > MAX_COLOUR_LEVELS) {
        showNotification(sprintf("'%s' tiene más de %d valores: no se usa para el color.",
                                 aes_label(colour_by), MAX_COLOUR_LEVELS), type = "warning")
      } else if (is.numeric(v)) {
        p$data$colour <- v
        p <- p + aes(colour = .data$colour) + scale_colour_viridis_c(end = 0.85)
        colour_label <- aes_label(colour_by)
      } else {
        v <- as.factor(v)
        p$data$colour <- v
        p <- p + aes(colour = .data$colour) +
          scale_colour_manual(values = discrete_palette(levels(v)))
        colour_label <- aes_label(colour_by)
      }
    }

    shape_by <- input$shape_by
    v <- aes_values(shape_by, emb, df)
    if (!is.null(v)) {
      v <- as.factor(v)
      if (nlevels(v) > MAX_SHAPE_LEVELS) {
        showNotification(sprintf("'%s' tiene más de %d valores: no se usa para la forma.",
                                 aes_label(shape_by), MAX_SHAPE_LEVELS), type = "warning")
      } else {
        p$data$shape <- v
        p <- p + aes(shape = .data$shape)
        shape_label <- aes_label(shape_by)
      }
    }

    p +
      geom_point(size = 2.2, alpha = 0.85) +
      labs(x = colnames(emb$coords)[1], y = colnames(emb$coords)[2],
           colour = colour_label, shape = shape_label) +
      theme_minimal(base_size = 14)
  })

  output$association <- DT::renderDT({
    emb <- embedding()
    validate(need(!is.null(emb$clusters), "Esta ejecución no tiene agrupamiento."))
    a <- tryCatch(cluster_association(emb$X, emb$clusters), error = function(e) e)
    validate(need(!inherits(a, "error"), if (inherits(a, "error")) conditionMessage(a)))
    shown <- data.frame(Variable = a$variable, `η²` = round(a$eta2, 3),
                        Cluster = a$cluster, Diferencia = round(a$diff, 2),
                        check.names = FALSE)
    DT::datatable(shown, rownames = FALSE, selection = "none",
                  options = list(pageLength = 10, language = list(search = "Buscar:")))
  })

  output$run_summary <- renderText({
    req(last_run$method)
    summarise_run(reactiveValuesToList(last_run))
  })

  # P5: report of the last run. The button only exists once a run has finished,
  # so there is never an empty report to download.
  output$report_button <- renderUI({
    req(last_run$method)
    div(style = "margin: 10px 0;",
        downloadButton("download_report", "Descargar informe (HTML)"))
  })

  output$download_report <- downloadHandler(
    filename = function() report_filename(last_run$time),
    content = function(file) {
      emb <- embedding()
      html <- build_report(reactiveValuesToList(last_run), last_run$time,
                           X = emb$X, clusters = emb$clusters)
      writeLines(enc2utf8(html), file, useBytes = TRUE)
    },
    contentType = "text/html; charset=utf-8"
  )
}

shinyApp(ui = ui, server = server)

# Cluster labels for the rows of X, the output of prepare_matrix().
#
# Every method works on X and nothing else (never on the embedding), so the
# clusters and the embedding of a run come from the same matrix and rows.
# Noise points of DBSCAN and HDBSCAN (label 0 in dbscan) get the level
# NOISE_LABEL, placed last, instead of being treated as one more cluster.
#
# Returns a factor of length nrow(X) with attr(, "params"): method, the
# parameters used, the seed (k-means only) and the clustering columns.
NOISE_LABEL <- "ruido"
CLUSTER_METHODS <- c("k-means", "DBSCAN", "HDBSCAN")

get_clusters <- function(X, method = CLUSTER_METHODS, seed = NULL,
                         centers = 2, nstart = 10, eps = 0.5, minpts = 5) {
  method <- match.arg(method)
  if (!is.matrix(X) || !is.numeric(X)) {
    stop("El agrupamiento necesita la matriz numérica de prepare_matrix().", call. = FALSE)
  }
  n <- nrow(X)

  if (method == "k-means") {
    centers <- as.integer(centers)
    if (is.na(centers) || centers < 1 || centers >= n) {
      stop(sprintf("El número de centros tiene que estar entre 1 y %d.", n - 1),
           call. = FALSE)
    }
    nstart <- max(1L, as.integer(nstart))
    if (!is.null(seed)) set.seed(seed)
    labels <- stats::kmeans(X, centers = centers, nstart = nstart)$cluster
    params <- list(method = method, centers = centers, nstart = nstart, seed = seed)
  } else if (method == "DBSCAN") {
    if (!is.finite(eps) || eps <= 0) {
      stop("eps tiene que ser positivo.", call. = FALSE)
    }
    minpts <- as.integer(minpts)
    if (is.na(minpts) || minpts < 1) {
      stop("Los puntos mínimos tienen que ser al menos 1.", call. = FALSE)
    }
    labels <- dbscan::dbscan(X, eps = eps, minPts = minpts)$cluster
    params <- list(method = method, eps = eps, minPts = minpts)
  } else {
    minpts <- as.integer(minpts)
    if (is.na(minpts) || minpts < 2 || minpts >= n) {
      stop(sprintf("Los puntos mínimos de HDBSCAN tienen que estar entre 2 y %d.", n - 1),
           call. = FALSE)
    }
    labels <- dbscan::hdbscan(X, minPts = minpts)$cluster
    params <- list(method = method, minPts = minpts)
  }

  params$vars <- colnames(X)
  out <- as_cluster_factor(labels)
  attr(out, "params") <- params
  out
}

# Integer labels (0 = noise) to a factor: clusters in numeric order, noise last.
as_cluster_factor <- function(labels) {
  ids <- sort(unique(labels[labels != 0]))
  chr <- ifelse(labels == 0, NOISE_LABEL, as.character(labels))
  levels <- as.character(ids)
  if (any(labels == 0)) levels <- c(levels, NOISE_LABEL)
  factor(chr, levels = levels)
}

# Size of each cluster, noise apart.
cluster_sizes <- function(cl) {
  tab <- table(cl)
  list(sizes = tab[names(tab) != NOISE_LABEL],
       noise = if (NOISE_LABEL %in% names(tab)) unname(tab[[NOISE_LABEL]]) else 0L)
}

# Discrete palette readable on a white background: Okabe-Ito without yellow,
# then a dark HCL palette when there are more levels; noise in grey.
discrete_palette <- function(levels) {
  okabe_ito <- c("#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00", "#56B4E9",
                 "#000000")
  regular <- setdiff(levels, NOISE_LABEL)
  cols <- if (length(regular) <= length(okabe_ito)) {
    okabe_ito[seq_along(regular)]
  } else {
    grDevices::hcl.colors(length(regular), "Dark 3")
  }
  pal <- stats::setNames(cols, regular)
  if (NOISE_LABEL %in% levels) pal[NOISE_LABEL] <- "grey60"
  pal
}

# Column roles:
#   "cluster" - enters the matrix that every method (P2, P3) works on;
#   "display" - only used to colour or shape plots;
#   "ignore"  - not used at all.
ROLES <- c("cluster", "display", "ignore")

# Default role per column: numeric -> "cluster", anything else -> "display".
default_roles <- function(df) {
  is_num <- vapply(df, is.numeric, logical(1))
  stats::setNames(ifelse(is_num, "cluster", "display"), names(df))
}

# Numeric, standardised matrix with the "cluster" columns of df and nothing else.
#
# Rows with missing values in those columns and constant columns are dropped
# with a warning. The indices of the rows kept (relative to df) are returned in
# attr(X, "rows"), so display variables can be matched to the rows of X.
prepare_matrix <- function(df, roles) {
  stopifnot(is.data.frame(df), is.character(roles))
  missing_roles <- setdiff(names(df), names(roles))
  if (length(missing_roles) > 0) {
    stop("Faltan papeles para las columnas: ", paste(missing_roles, collapse = ", "),
         call. = FALSE)
  }
  unknown <- setdiff(unique(roles), ROLES)
  if (length(unknown) > 0) {
    stop("Papel desconocido: ", paste(unknown, collapse = ", "), call. = FALSE)
  }

  cols <- names(df)[roles[names(df)] == "cluster"]
  if (length(cols) == 0) {
    stop("Ninguna columna tiene el papel de agrupamiento.", call. = FALSE)
  }
  non_numeric <- cols[!vapply(df[cols], is.numeric, logical(1))]
  if (length(non_numeric) > 0) {
    stop("Las columnas de agrupamiento deben ser numéricas: ",
         paste(non_numeric, collapse = ", "), call. = FALSE)
  }

  X <- as.matrix(df[cols])
  storage.mode(X) <- "double"
  rows <- seq_len(nrow(X))

  complete <- stats::complete.cases(X)
  if (!all(complete)) {
    warning(sprintf(
      "Se han descartado %d fila(s) con valores faltantes en las columnas de agrupamiento.",
      sum(!complete)
    ), call. = FALSE)
    X <- X[complete, , drop = FALSE]
    rows <- rows[complete]
  }
  if (nrow(X) < 2) {
    stop("Quedan menos de 2 filas completas.", call. = FALSE)
  }

  constant <- apply(X, 2, function(v) stats::sd(v) == 0)
  if (any(constant)) {
    warning("Se han descartado columnas constantes: ",
            paste(colnames(X)[constant], collapse = ", "), call. = FALSE)
    X <- X[, !constant, drop = FALSE]
  }
  if (ncol(X) == 0) {
    stop("No queda ninguna columna de agrupamiento no constante.", call. = FALSE)
  }

  X <- scale(X)
  attr(X, "rows") <- rows
  X
}

# 2-D embedding of the rows of X, the output of prepare_matrix() (already
# standardised, so PCA neither centres nor scales again).
#
# The seed is set right before each stochastic call (t-SNE, UMAP). Returns an
# n x 2 matrix with attr(, "params"): the parameters actually used, which may
# differ from the requested ones (perplexity, n_neighbors are capped by n).
reduce_dim <- function(X, method = c("PCA", "t-SNE", "UMAP"), seed = NULL,
                       perplexity = 30, n_neighbors = 15) {
  method <- match.arg(method)
  X <- as.matrix(X)
  n <- nrow(X)
  if (ncol(X) < 2) {
    stop("Hacen falta al menos 2 variables de agrupamiento para un gráfico en 2-D.",
         call. = FALSE)
  }

  if (method == "PCA") {
    pc <- stats::prcomp(X, center = FALSE, scale. = FALSE)
    coords <- pc$x[, 1:2, drop = FALSE]
    var_explained <- pc$sdev^2 / sum(pc$sdev^2)
    params <- list(method = "PCA", variance_explained = var_explained[1:2])
    colnames(coords) <- c("PC1", "PC2")
  } else if (method == "t-SNE") {
    # Rtsne requires 3 * perplexity <= n - 1.
    max_perplexity <- (n - 1) / 3
    if (max_perplexity < 1) {
      stop("t-SNE necesita al menos 4 filas.", call. = FALSE)
    }
    used <- min(perplexity, max_perplexity)
    if (!is.null(seed)) set.seed(seed)
    fit <- Rtsne::Rtsne(X, dims = 2, perplexity = used, check_duplicates = FALSE)
    coords <- fit$Y
    params <- list(method = "t-SNE", perplexity = used,
                   perplexity_requested = perplexity, seed = seed)
    colnames(coords) <- c("tSNE1", "tSNE2")
  } else {
    if (n < 3) {
      stop("UMAP necesita al menos 3 filas.", call. = FALSE)
    }
    config <- umap::umap.defaults
    config$n_neighbors <- min(n_neighbors, n - 1)
    if (!is.null(seed)) {
      config$random_state <- seed
      set.seed(seed)
    }
    fit <- umap::umap(X, config = config)
    coords <- fit$layout
    params <- list(method = "UMAP", n_neighbors = config$n_neighbors,
                   n_neighbors_requested = n_neighbors, seed = seed)
    colnames(coords) <- c("UMAP1", "UMAP2")
  }

  rownames(coords) <- NULL
  attr(coords, "params") <- params
  coords
}

# Give `role` to the columns `cols` of df, starting from the named vector
# `roles` (one entry per column of df, see ROLES in prepare_matrix.R).
#
# Text columns cannot take the "cluster" role: they keep their role and are
# returned in attr(, "rejected"), so the caller can say why nothing changed.
assign_role <- function(roles, cols, role, df) {
  stopifnot(is.character(roles), is.data.frame(df), identical(names(roles), names(df)))
  if (!role %in% ROLES) stop("Papel desconocido: ", role, call. = FALSE)
  cols <- intersect(cols, names(df))
  rejected <- character()
  if (role == "cluster") {
    is_num <- vapply(df[cols], is.numeric, logical(1))
    rejected <- cols[!is_num]
    cols <- cols[is_num]
  }
  roles[cols] <- role
  attr(roles, "rejected") <- rejected
  roles
}

# Number of columns with each role, in the order of ROLES.
count_roles <- function(roles) {
  stats::setNames(vapply(ROLES, function(r) sum(roles == r), integer(1)), ROLES)
}

# One-line summary of a run, shown under the plot. `run` is a plain list with
# the fields of last_run in app.R: method, params (from reduce_dim), seed,
# n_rows, n_rows_dropped, cluster_vars, cluster_params (from get_clusters,
# NULL without clustering), cluster_sizes and n_noise.
summarise_run <- function(run) {
  fmt <- function(x) format(signif(x, 4), trim = TRUE)
  p <- run$params

  dimred <- switch(
    run$method,
    "t-SNE" = if (p$perplexity < p$perplexity_requested) {
      sprintf("t-SNE (perplejidad %s, reducida desde %s)", fmt(p$perplexity),
              fmt(p$perplexity_requested))
    } else {
      sprintf("t-SNE (perplejidad %s)", fmt(p$perplexity))
    },
    "UMAP" = sprintf("UMAP (n_neighbors %d)", as.integer(p$n_neighbors)),
    run$method
  )

  cp <- run$cluster_params
  clustering <- if (is.null(cp)) {
    "sin agrupamiento"
  } else {
    desc <- switch(
      cp$method,
      "k-means" = sprintf("k-means (%d centros, nstart %d)", cp$centers, cp$nstart),
      "DBSCAN" = sprintf("DBSCAN (eps %s, minPts %d)", fmt(cp$eps), cp$minPts),
      "HDBSCAN" = sprintf("HDBSCAN (minPts %d)", cp$minPts)
    )
    sizes <- if (length(run$cluster_sizes) == 0) {
      "ningún cluster"
    } else {
      sprintf("%d cluster(s) de %s", length(run$cluster_sizes),
              paste(run$cluster_sizes, collapse = ", "))
    }
    paste0(desc, ": ", sizes, if (run$n_noise > 0) sprintf(", ruido %d", run$n_noise))
  }

  sprintf("%s · %s · semilla %s · %d filas (%d descartadas) × %d variables de agrupamiento",
          dimred, clustering, run$seed, run$n_rows, run$n_rows_dropped,
          length(run$cluster_vars))
}
